INSERT INTO public.shotlist_templates (service_type, session_type, item_name, category, technical_note) VALUES
('Wedding', 'Akad', 'Ijab Kabul', 'Wajib', 'Gunakan lensa medium (35mm/50mm), pastikan depth of field cukup (f/2.8 - f/4) untuk menangkap ekspresi pengantin pria, penghulu, dan wali nikah secara tajam.'),
('Wedding', 'Akad', 'Tukar Cincin', 'Wajib', 'Gunakan lensa makro atau telephoto (85mm/100mm) untuk extreme close-up. Fokus tajam pada cincin dan jari, hindari blocking dari tangan penghulu/keluarga.'),
('Wedding', 'Akad', 'Penandatanganan Buku Nikah', 'Wajib', 'Ambil dua angle: Wide angle (16mm-24mm) untuk menunjukkan suasana keseluruhan meja akad, dan Medium/Detail untuk momen pena menyentuh buku nikah.'),
('Wedding', 'Akad', 'Sungkeman', 'Wajib', 'Kombinasi kamera: Cam 1 (Wide 24mm) memotret keseluruhan susunan keluarga dari samping/belakang, Cam 2 (Tele 85mm/135mm) mengunci close-up pada mata/air mata yang jatuh. Gunakan silent shutter.'),
('Wedding', 'Akad', 'Penyerahan Mahar', 'Wajib', 'Fokus pada senyum pengantin dan detail mahar yang diserahkan. Gunakan lighting tambahan (bounce flash) jika pencahayaan ruangan kurang merata.'),
('Wedding', 'Akad', 'Air Mata Haru / Emosi Keluarga', 'Secondary', 'Candid shot menggunakan lensa telephoto (70-200mm). Pantau reaksi ibu/ayah pengantin dari kejauhan tanpa mengganggu momen khidmat.'),
('Wedding', 'Akad', 'Detail Dekorasi Meja Akad & Cincin', 'Secondary', 'Shallow depth of field (f/1.4 - f/1.8). Fokus pada tekstur bunga, ukiran kotak cincin, atau elemen estetis lainnya sebelum sesi dimulai.'),
('Wedding', 'Akad', 'Refleksi Cermin saat Make-up (Paes)', 'Kreatif', 'Manfaatkan frame-in-frame atau pantulan cermin rias dengan komposisi rule of thirds. Fokus pada mata pengantin di cermin.'),
('Wedding', 'Resepsi', 'Masuk Pengantin (Kirab Adat)', 'Wajib', 'Lensa wide (16-35mm) atau medium. Gunakan continuous AF (AF-C) dan burst mode untuk menangkap pergerakan langkah yang dinamis beserta iring-iringan cucuk lampah.'),
('Wedding', 'Resepsi', 'Foto di Pelaminan', 'Wajib', 'Lensa standar/medium (35-50mm), aperture tertutup (f/5.6 - f/8) agar semua anggota keluarga/tamu in-focus (Full body). Lighting flat dan merata (off-camera flash wajib).'),
('Wedding', 'Resepsi', 'Lempar Bunga / Handbouquet', 'Wajib', 'Gunakan shutter speed tinggi (min. 1/500s) untuk membekukan momen bunga di udara. Angle dari bawah (low angle) dapat menambah kesan dramatis.'),
('Wedding', 'Resepsi', 'Salaman dengan Tamu', 'Secondary', 'Candid framing. Jangan ambil semua tamu, cukup ambil ekspresi paling natural (tertawa lepas, pelukan hangat) menggunakan medium-tele.'),
('Wedding', 'Resepsi', 'Detail Riasan / Paes Ageng', 'Secondary', 'Close-up shot. Fokus sangat tajam (pin-point AF) pada cunduk mentul, alis menjangan, atau detail roncean melati.'),
('Wedding', 'Resepsi', 'Siluet Pengantin di Lorong / Backlight', 'Kreatif', 'Eksplorasi rim light. Tempatkan flash di belakang pengantin (backlight) atau gunakan sumber cahaya alami jendela untuk menciptakan siluet estetik.'),
('Graduation', 'Private Portrait', 'Foto Bersama Orang Tua', 'Wajib', 'Lensa 35mm atau 50mm. Full body composition. Pastikan ruang di atas kepala (headroom) cukup dan posisi bahu proporsional (tidak distorsi).'),
('Graduation', 'Private Portrait', 'Pegang Ijazah / Tabung', 'Wajib', 'Medium close-up (waist-up). Arahkan model untuk memiringkan tabung sedikit ke arah cahaya utama. Fokus tegas pada mata dan logo universitas di tabung.'),
('Graduation', 'Private Portrait', 'Gordon / Atribut Universitas', 'Secondary', 'Lensa makro atau bukaan lebar (f/1.8). Ekstrem close-up pada tekstur gordon, kalung medali, atau detail bordir kebaya/jas.'),
('Graduation', 'Private Portrait', 'Tertawa Lepas / Interaksi', 'Secondary', 'Candid. Pancing interaksi atau lelucon agar subjek tertawa senatural mungkin. Gunakan burst mode dengan eye-tracking AF.'),
('Graduation', 'Private Portrait', 'Toss Toga di Udara', 'Kreatif', 'Low angle ekstrem. Shutter speed super cepat (1/1000s+). Jika outdoor, letakkan matahari di belakang subjek untuk efek sun-flare.');
